mapper.sql:
where tm.owner_user_id = #{ownerUserId}
  and tm.deleted_at is null

    and (lower(u.user_id) like #{keywordPattern}
        or lower(u.unified_auth_id) like #{keywordPattern}
        or lower(u.username) like #{keywordPattern}
        or lower(coalesce(u.organization, '')) like #{keywordPattern}
        or lower(coalesce(u.rd_department, '')) like #{keywordPattern}
        or lower(coalesce(u.department, '')) like #{keywordPattern})

where u.status = 'ACTIVE'
  and u.user_id <> #{ownerUserId}
  and not exists (
      select 1 from system_admin_team_members tm
      where tm.owner_user_id = #{ownerUserId}
        and tm.member_user_id = u.user_id
        and tm.deleted_at is null
  )

    and (lower(u.user_id) like #{keywordPattern}
        or lower(u.unified_auth_id) like #{keywordPattern}
        or lower(u.username) like #{keywordPattern}
        or lower(coalesce(u.organization, '')) like #{keywordPattern}
        or lower(coalesce(u.rd_department, '')) like #{keywordPattern}
        or lower(coalesce(u.department, '')) like #{keywordPattern})

mapper.update:
update system_admin_team_members
set deleted_at = #{deletedAt}, updated_at = #{deletedAt}
where owner_user_id = #{ownerUserId} and member_user_id = #{memberUserId} and deleted_at is null
